  const body = '<div class="jh-finance__pad">' + kpi + pers + vatNote + lock + skip + (rows.length ? tbl([['계정 이동'], ['건수', 'num'], ['금액', 'num']], rows) : '<div class="jh-empty">계정이 바뀌는 전표가 없습니다.</div>') + '<div class="jh-finance__bar"><button type="button" class="jh-btn" data-variant="primary" data-act="rr-run"' + (rr.running || !(n + sm) ? ' disabled' : '') + '>' + esc(n) + '건 재분류 + ' + esc(sm) + '건 확인 완료 표시 실행</button><span class="jh-field__hint" data-rr-progress role="status">' + esc(rr.progress || '') + '</span></div><span class="jh-field__hint">전표마다 원 전표는 역분개되고 같은 일자의 새 전표가 만들어집니다(저장한 사람이 감사 기록에 남습니다). 중간에 멈춰도 다시 누르면 남은 전표만 처리합니다.</span>' + res + '</div>';
