  const pRows = R.purchase.map((r, i) => '<tr><td>' + esc(r.key) + '</td><td>' + esc(r.name || '') + '</td><td><select class="jh-select" data-pr="' + i + '">' + accOpts(r.account) + '</select></td><td>' + esc(r.memo || '') + '</td><td><button type="button" class="jh-btn" data-variant="ghost" data-pr-del="' + i + '">삭제</button></td></tr>');
  const pCard = '<div class="jh-finance__pad"><div class="jh-finance__bar"><input class="jh-input jh-finance__q" data-pr-key placeholder="사업자번호(10자리) 또는 상호"><select class="jh-select" data-pr-acc>' + accOpts('5210') + '</select><button type="button" class="jh-btn" data-variant="ghost" data-act="pr-add">규칙 추가</button><button type="button" class="jh-btn" data-variant="primary" data-act="rules-save-p"' + (R.dirtyP ? '' : ' disabled') + '>변경 저장</button><span class="jh-field__hint">' + (R.dirtyP ? '저장하지 않은 변경이 있습니다' : '') + '</span></div><span class="jh-field__hint">홈택스 매입 가져오기에서 이 거래처가 나오면 정한 계정이 자동으로 들어갑니다. 가져오기 미리보기에서 "이 거래처는 항상"을 체크해도 여기에 쌓입니다.</span></div>' + (pRows.length ? tbl([['사업자번호·상호'], ['이름'], ['계정'], ['메모'], ['']], pRows, 'jh-fin-table--form') : '<div class="jh-empty">저장된 매입 거래처 규칙이 없습니다.</div>');
