/* ───────── 월별 매출 세 숫자(대표님 2026-10-21 "제이에이치 전체 매출 정보가 있어야 하고 솔루션→이엔지 계산서도 취합해야 세무 계획을 짤 수 있다") ─────────
 * 청구서(이엔지 명의, 서버 invoiceMonthly)·세금계산서(솔루션→이엔지, 공급가·부가세 포함 합계)·통장 입금(이엔지→솔루션)을 월별 한 줄과 연 합계로 나란히 둔다. 서로 다른 거래의 서류라 같지 않은 것이 정상이며 짝짓지 않는다.
 * inv = { state: idle|loading|ok|error|denied, error }, T = revenueTriple 결과. 청구서를 못 받아도 세금계산서·통장 입금은 항상 보여 준다. ok 라는데 응답이 이상하면(T.invoiceReady 거짓) 0원으로 보이지 않게 오류로 다룬다 */
export function revenueTripleHtml(inv, T) {
  const iv = inv && typeof inv === 'object' ? inv : {}; const t = T && typeof T === 'object' && Array.isArray(T.rows) && Array.isArray(T.years) ? T : { rows: [], years: [], invoiceReady: false };
  const state = iv.state === 'ok' && !t.invoiceReady ? 'badok' : (iv.state || 'idle'); const err = state === 'badok' ? '청구서 매출을 불러오지 못했습니다(서버 응답 형식이 올바르지 않습니다).' : String(iv.error || '청구서 매출을 불러오지 못했습니다.');
  const reload = '<button type="button" class="jh-btn" data-variant="ghost" data-inv-reload>다시 불러오기</button>';
  const status = state === 'loading' ? '<div class="jh-field__hint">청구서 매출을 불러오는 중…</div>' : state === 'error' || state === 'badok' ? '<div class="jh-field__hint" data-tone="warn">' + esc(err) + '</div><div class="jh-field__hint">' + reload + '</div>' : state === 'denied' ? '<div class="jh-field__hint" data-tone="warn">청구서 매출은 재무회계 권한이 있는 계정만 볼 수 있습니다.</div>' : '';
  const fin = (v) => typeof v === 'number' && Number.isFinite(v); const inc = (v) => (fin(v) ? esc(won(v)) : '');
  const invCell = (r) => (fin(r.invSupply) ? esc(won(r.invSupply)) + '<span class="jh-field__hint"> 완결 ' + esc(won(r.invDone)) + ' · 미완결 ' + esc(won(r.invOpen)) + '</span>' : '');
  const open = t.invoiceReady ? t.years.reduce((a, y) => a + (fin(y.invOpen) ? y.invOpen : 0), 0) : 0;
  const warn = open > 0 ? '<div class="jh-alert" data-tone="warn" role="note">미완결 ' + esc(won(open)) + '원은 아직 프로젝트 매출에 포함되지 않았습니다. 수금이 끝난 청구서는 영업기획 정산서에서 완결 처리해 주세요.</div>' : '';
  const rows = t.rows.map((r) => '<tr><td>' + esc(r.ym) + '</td><td class="num"' + (fin(r.invOpen) && r.invOpen > 0 ? ' data-tone="warn"' : '') + '>' + invCell(r) + '</td><td class="num">' + inc(r.taxSupply) + '</td><td class="num">' + inc(r.taxTotal) + '</td><td class="num">' + inc(r.bank) + '</td></tr>');
  const yrs = t.years.map((y) => '<tr><td><strong>' + esc(y.year) + ' 합계</strong></td><td class="num"><strong>' + (fin(y.invSupply) ? esc(won(y.invSupply)) : '') + '</strong>' + (fin(y.invSupply) ? '<span class="jh-field__hint"> 완결 ' + esc(won(y.invDone)) + ' · 미완결 ' + esc(won(y.invOpen)) + '</span>' : '') + '</td><td class="num"><strong>' + inc(y.taxSupply) + '</strong></td><td class="num"><strong>' + inc(y.taxTotal) + '</strong></td><td class="num"><strong>' + inc(y.bank) + '</strong></td></tr>');
  const note = '<div class="jh-alert" data-tone="info" role="note">세 숫자는 서로 다른 서류입니다 — 청구서(이엔지→발주처, 제이에이치 전체 매출)·세금계산서(솔루션→이엔지, 세금 신고)·통장 입금(이엔지→솔루션, 실제로 받은 돈). 금액과 시기가 같지 않은 것이 정상이며 짝짓지 않습니다.</div>';
  const table = rows.length ? tbl([['월'], ['청구서(공급가)', 'num'], ['세금계산서(공급가)', 'num'], ['세금계산서(합계·부가세 포함)', 'num'], ['통장 입금', 'num']], rows.concat(yrs)) : '<div class="jh-empty">아직 표시할 매출이 없습니다.</div>';
  return card('월별 매출 세 숫자(최근 달이 위)', '<div class="jh-finance__pad">' + note + warn + status + table + '</div>', '', true);
}
/* ───────── 이엔지 정산(계산서와 실제 입금의 차이 처리) ───────── */
export function gapHtml(st) {
  const rows = arByMonth(st.entries); const bal = rows.length ? rows[rows.length - 1].balance : 0; const lastD = st.entries.reduce((m, e) => (e.date > m ? e.date : m), '') || kstToday();
  const tr = rows.slice().reverse().map((r) => '<tr><td>' + esc(r.ym) + '</td>' + num(r.billed) + num(r.received) + num(r.adjusted) + num(r.other) + '<td class="num"><strong>' + esc(won(r.balance)) + '</strong></td></tr>');
  const adj = st.entries.filter((e) => e.source && /^enj_gap/.test(e.source.id || '') && !e.reversedBy).sort((a, b) => (a.date < b.date ? 1 : -1)); const opts = GAP_TYPES.map(([k, l]) => '<option value="' + k + '">' + esc(l) + '</option>').join('');
  const form = '<div class="jh-finance__pad"><div class="jh-alert" data-tone="warn" role="note">세금계산서 발행액보다 실제로 받은 돈이 적은 차이를 정리하는 곳입니다. <strong>증빙이 있는 처리</strong>(현금 수령, 상계)는 증빙 내용을 적어야 저장되고, 증빙이 없으면 "증빙 없음"으로 매출에서 차감해 장부가 사실과 다르지 않게 합니다. 잔액이 실제 받을 돈이면 처리하지 마세요.</div>' +
    '<div class="jh-finance__two"><div><div class="jh-field"><label class="jh-field__label">처리 방식</label><select class="jh-select" data-g="type">' + opts + '</select></div><div class="jh-field"><label class="jh-field__label">처리 일자</label><input class="jh-input" type="date" data-g="date" value="' + esc(lastD) + '"></div><div class="jh-field"><label class="jh-field__label">금액(원)</label><input class="jh-input" data-g="amount" inputmode="numeric" value="' + esc(bal > 0 ? won(bal) : '') + '"><span class="jh-field__hint">기본값은 현재 외상매출금 잔액입니다. 일부만 처리해도 됩니다.</span></div></div><div><div class="jh-field"><label class="jh-field__label">증빙 내용(증빙 있는 처리는 필수)</label><input class="jh-input" data-g="evidence" maxlength="120" placeholder="예: 상계 합의서 2026-08-31, 현금 영수증 번호"></div><div class="jh-field"><label class="jh-field__label">메모(선택)</label><input class="jh-input" data-g="memo" maxlength="80"></div><div class="jh-field__hint">저장 후 전표 상세에서 <strong>증빙 파일을 붙일 수 있습니다</strong>.</div></div></div><div class="jh-alert" data-tone="info" data-g-result>입력하면 전표 모양이 여기에 나옵니다.</div><div class="jh-finance__bar"><button type="button" class="jh-btn" data-variant="primary" data-act="gap-save">처리 전표 저장</button></div></div>';
  const hist = adj.length ? '<ul class="jh-finance__list">' + adj.map((e) => '<li class="jh-finance__li" data-entry="' + esc(e.id) + '" tabindex="0"><div><strong>' + esc(e.date) + ' · ' + esc(e.memo.length > 46 ? e.memo.slice(0, 46) + '…' : e.memo) + '</strong><span class="jh-field__hint">' + esc(e.no) + (e.attachments && e.attachments.length ? ' · 증빙 ' + e.attachments.length + '개' : ' · 증빙 파일 없음') + '</span></div><span class="jh-finance__amt">' + esc(won(entryDebit(e))) + '</span></li>').join('') + '</ul>' : '<div class="jh-empty">처리한 내역이 없습니다.</div>';
  return '<div class="jh-finance__split"><div class="jh-finance__col">' + revenueTripleHtml(st.inv, st.revT) + card('이엔지 외상매출금 월별(최근 달이 위)', rows.length ? tbl([['월'], ['청구(계산서)', 'num'], ['입금', 'num'], ['정산 차액 처리', 'num'], ['기타(공제·상계 등)', 'num'], ['월말 잔액', 'num']], tr) : '<div class="jh-empty">외상매출금 거래가 없습니다.</div>', '', true) + card('차액 처리', form) + '</div><div class="jh-finance__col">' + card('현재 잔액', '<div class="jh-finance__pad"><div class="jh-finance__fact"><span>외상매출금 잔액(실제로 받을 돈이어야 함)</span><strong>' + esc(won(bal)) + '</strong></div></div>') + card('처리한 내역', hist, '', true) + '</div></div>';
}

/* ───────── 마감 전 점검 ───────── */
export function closeCheckHtml(result, through) {
  if (!result) return '<div class="jh-field__hint">마감하기 전에 "점검"을 눌러 장부가 맞는지 확인하세요.</div>';
  const icon = { ok: '✅', warn: '⚠', bad: '❌' }; const head = result.bad ? alertHtml('danger', '문제 ' + result.bad + '건 — 해결한 뒤 마감하세요') : (result.warn ? alertHtml('warn', '확인할 것 ' + result.warn + '건이 있습니다 — 알고 마감하려면 계속하세요') : alertHtml('info', '모두 통과했습니다'));
  return head + '<ul class="jh-finance__list">' + result.checks.map((c) => '<li class="jh-finance__li"><div><strong>' + icon[c.level] + ' ' + esc(c.label) + '</strong><span class="jh-field__hint">' + esc(c.detail) + '</span></div></li>').join('') + '</ul><div class="jh-field__hint">' + esc(through) + ' 까지 기준</div>';
}

/** 일괄 재분류 패널 — info: { count, total, fromOptions:[{code,name,n}], defaultFrom, lockedNote } */
export function bulkReclassHtml(info) {
  const fromOpts = info.fromOptions.map((o) => '<option value="' + esc(o.code) + '"' + (o.code === info.defaultFrom ? ' selected' : '') + '>' + esc(o.code + ' ' + o.name + ' (' + o.n + '건)') + '</option>').join('');
  const fact = (l, v) => '<div class="jh-finance__fact"><span>' + esc(l) + '</span><strong>' + esc(v) + '</strong></div>';
  return '<div class="jh-finance__pad">' + alertHtml('info', '고른 전표마다 "바꿀 계정" 줄을 "새 계정"으로 바꿔 역분개 + 새 전표를 만듭니다. 원 전표와 역분개 전표는 그대로 남습니다.') + '<div class="jh-finance__facts">' + fact('선택한 전표', info.count + '건') + fact('금액 합계(차변)', won(info.total) + '원') + '</div>'
    + '<div class="jh-field"><label class="jh-field__label">바꿀 계정(현재)</label><select class="jh-select" data-bk-from>' + fromOpts + '</select></div>'
    + '<div class="jh-field"><label class="jh-field__label">새 계정</label><select class="jh-select" data-bk-to>' + accOptions('') + '</select></div>'
    + '<div class="jh-field"><label class="jh-field__label">거래처(선택)</label><input class="jh-input" data-bk-partner maxlength="60" placeholder="비우면 각 전표의 거래처를 그대로 둡니다(옛 분류 대기 표시는 지워집니다)"></div>'
    + '<div class="jh-field"><label class="jh-field__label">새 전표 일자</label><label class="jh-finance__check"><input type="radio" name="bkd" value="keep" data-bk-datemode checked> 각 전표의 원래 일자로(권장)</label><label class="jh-finance__check"><input type="radio" name="bkd" value="fixed" data-bk-datemode> 하나로 지정</label><input class="jh-input" type="date" data-bk-date aria-label="새 전표 일자" disabled><span class="jh-field__hint">' + esc(info.lockedNote || '') + '</span></div>'
    + '<div class="jh-field"><label class="jh-field__label">사유·메모(선택)</label><input class="jh-input" data-bk-memo maxlength="200" placeholder="모든 새 전표에 같은 메모가 들어갑니다"></div>'
    + '<div class="jh-finance__bar"><button type="button" class="jh-btn" data-variant="primary" data-bk-run>일괄 재분류 실행</button></div><div data-bk-progress class="jh-field__hint"></div></div>';
}
/** 전표 상세 안 "계정 바꾸기" 패널 — 줄마다 계정을 고르고 일자·메모를 정해 저장(역분개 + 새 전표) */
export function reclassHtml(e, defaultDate) {
  const rows = e.lines.map((l, i) => '<tr><td><select class="jh-select" data-rc-acc="' + i + '">' + accOptions(l.account) + '</select></td><td><input class="jh-input" data-rc-partner="' + i + '" data-rc-init="' + esc(/^분류 대기/.test(l.partner || '') ? '' : (l.partner || '')) + '" value="' + esc(/^분류 대기/.test(l.partner || '') ? '' : (l.partner || '')) + '" maxlength="60" placeholder="거래처(선택)" aria-label="거래처"></td><td>' + esc(l.side === 'D' ? '차변' : '대변') + '</td>' + num(l.amount) + '</tr>');
  return '<div class="jh-finance__pad">' + alertHtml('info', '원 전표를 역분개하고 고른 계정·거래처로 새 전표를 만듭니다. 원 전표와 역분개 전표는 그대로 남아 기록이 지워지지 않습니다. 옛 분류 대기 거래처 표시는 계정을 바꾸면 지워집니다.') + tbl([['계정'], ['거래처'], ['차/대'], ['금액', 'num']], rows, 'jh-fin-table--form') + '<div class="jh-finance__bar"><input class="jh-input" type="date" data-rc-date value="' + esc(defaultDate) + '" aria-label="새 전표 일자"><input class="jh-input jh-finance__q" data-rc-memo maxlength="200" placeholder="사유·메모(선택)"><button type="button" class="jh-btn" data-variant="primary" data-act="reclass-save">재분류 저장</button></div><div class="jh-field__hint">일자는 기본으로 원 전표 일자(마감일 이후)가 들어가며, 역분개 전표와 새 전표가 이 날짜로 만들어집니다. 마감일 다음 날 이후만 가능합니다.</div></div>';
}


/* ───────── 프로젝트 표시(대기 목록) ───────── */
/** 전표 줄에 프로젝트를 붙이는 대기 목록 — 달별 카드. st = { rows, months, names, busy, msg, open, sel }. 계산은 pjt-tag-logic.js, 확정은 서버 pjtTagBatch(index.js 가 연결) */
/** 줄 직접 지정 패널 안쪽 — 한 줄을 프로젝트 하나 이상으로 나눠 직접 지정한다(서버 pjtTagSet). row = 대기 줄, names = { 프로젝트 id: 이름 }, draft = 입력 중이던 칸 [{ pjt, amount }](없으면 제안 분할, 그것도 없으면 빈 칸 하나).
 * 선택지의 값은 id, 보이는 글자는 이름이다. 목록에 없는 id(이미 지워진 프로젝트)가 칸에 있으면 그 id 를 선택지에 더해 몰래 바뀌지 않게 한다. 금액은 줄 금액을 항상 양수로 보여 준다(수정세금계산서 − 는 줄 목록의 표시). */
export function pjtSplitDialogHtml(row, names, draft) {
  const r = row || {}; const nm = names || {}; const fmt = (n) => Math.abs(Number(n) || 0).toLocaleString('ko-KR');
  const cells = (Array.isArray(draft) && draft.length ? draft : (Array.isArray(r.splits) && r.splits.length ? r.splits.map((x) => ({ pjt: x.pjt, amount: fmt(x.amount) })) : [{ pjt: '', amount: '' }]));
  const ids = Object.keys(nm).sort((a, b) => String(nm[a]).localeCompare(String(nm[b]), 'ko')); cells.forEach((c) => { if (c && c.pjt && ids.indexOf(c.pjt) === -1) ids.push(c.pjt); });
  const opts = (sel) => '<option value=""' + (sel ? '' : ' selected') + '>프로젝트 선택</option>' + ids.map((id) => '<option value="' + esc(id) + '"' + (id === sel ? ' selected' : '') + '>' + esc(nm[id] || id) + '</option>').join('');
  const cellHtml = (c) => '<div class="jh-fin__spcell"><select class="jh-select" data-sp-pjt aria-label="프로젝트">' + opts(c && c.pjt) + '</select><input class="jh-input" data-sp-amt inputmode="numeric" placeholder="금액" aria-label="금액" value="' + esc(c && c.amount != null ? c.amount : '') + '"></div>';
  return '<div class="jh-fin__spinfo"><strong>' + esc(r.no) + '</strong> · ' + esc(r.date) + ' · ' + esc(r.partner || '거래처 없음') + '<div class="jh-fin__ptmemo">' + esc(r.memo) + ' · ' + esc(r.account) + '</div><div class="num">줄 금액 ' + fmt(r.amount) + '원</div></div>'
    + '<div class="jh-fin__spcells" data-sp-cells data-sp-total="' + esc(Math.abs(Number(r.amount) || 0)) + '">' + cells.map(cellHtml).join('') + '</div>'
    + '<div class="jh-fin__spbar"><button type="button" class="jh-btn" data-variant="ghost" data-sp-add>+ 칸 추가</button><span class="jh-field__hint" data-sp-left role="status">' + esc(splitLeftText(r.amount, cells)) + '</span></div>'
    + '<div class="jh-field"><label class="jh-field__label" for="sp-note">메모(선택)</label><input class="jh-input" id="sp-note" data-sp-note maxlength="200" placeholder="예: 대표님 지정"></div>';
}
/** 확정된 줄 구역(수정·해제) — st.doneGroups = [{ month, rows, count }](최신 달부터, 순수 계산 buildConfirmedRows), st.doneOpen = 펼침 여부. 확정된 줄이 없으면 그리지 않는다. 처음에는 접혀 있고 토글에 줄 수만 보인다.
 * 줄마다 [수정](프로젝트 칸이 현재 지정으로 채워진 패널) · [해제](확인창 뒤 대기 목록으로 되돌림). 이전 지정은 서버 history 에 남고, 영업기획 마진율·월간 보고서 값이 바뀔 수 있다고 안내한다. nm = 프로젝트 id → 이름 함수, dis = 처리 중 비활성 속성 */
function doneHtml(st, nm, dis) {
  const groups = Array.isArray(st.doneGroups) ? st.doneGroups.filter((g) => g && Array.isArray(g.rows) && g.rows.length) : []; const n = groups.reduce((a, g) => a + g.rows.length, 0); if (!n) return '';
  const open = st.doneOpen === true; const money = (v) => esc(won(Math.abs(v)));
  const toggle = '<div class="jh-fin__donehead" data-pt-done><button type="button" class="jh-btn" data-variant="ghost" data-pt-done-toggle aria-expanded="' + (open ? 'true' : 'false') + '">확정된 줄 ' + n + '줄 ' + (open ? '접기 ▴' : '보기 ▾') + '</button></div>';
  if (!open) return '<section class="jh-card jh-fin__done">' + toggle + '</section>';
  const chips = (r) => (r.splits || []).map((x) => '<span class="jh-fin__chip">' + nm(x.pjt) + ' ' + (Math.abs(r.amount) ? Math.round(1000 * x.amount / Math.abs(r.amount)) / 10 : 0) + '%</span>').join('') || '<span class="jh-fin__chip jh-fin__chip--skip">프로젝트에 붙이지 않음' + (r.note ? ' · ' + esc(r.note) : '') + '</span>';
  const row = (r) => '<div class="jh-fin__donerow" data-pt-done-row="' + esc(r.id) + '"><div class="jh-fin__ptinfo"><strong>' + esc(r.no) + '</strong> · ' + esc(r.date) + ' · ' + esc(r.partner || '거래처 없음') + '<div class="jh-fin__ptmemo">' + esc(r.memo) + ' · ' + esc(r.account) + (r.method ? ' · ' + esc(r.method) : '') + (r.setByName ? ' · ' + esc(r.setByName) + ' 지정' : '') + (r.note ? ' · ' + esc(r.note) : '') + '</div></div>'
    + '<div class="jh-fin__ptchips">' + chips(r) + '</div><div class="num jh-fin__ptamt">' + (r.side === 'D' && /^4/.test(String(r.account)) ? '−' : '') + money(r.amount) + '</div>'
    + '<div class="jh-fin__doneact"><button type="button" class="jh-btn" data-pt-redo="' + esc(r.id) + '"' + dis + '>수정</button><button type="button" class="jh-btn" data-pt-undo="' + esc(r.id) + '"' + dis + '>해제</button></div></div>';
  const note = '<div class="jh-field__hint">이미 확정된 줄입니다. 수정하거나 해제하면 영업기획의 마진율·월간 보고서 값이 바뀔 수 있습니다. 이전 지정은 기록에 남습니다. 해제한 줄은 위 대기 목록으로 돌아옵니다.</div>';
  return '<section class="jh-card jh-fin__done">' + toggle + '<div class="jh-finance__pad">' + note + groups.map((g) => '<div class="jh-fin__donemonth"><h4>' + esc(g.month) + ' <span class="jh-fin__ptcount">' + g.rows.length + '줄</span></h4>' + g.rows.map(row).join('') + '</div>').join('') + '</div></section>';
}
/** 거래처 규칙 구역 — st.ruleOpen(펼침)·st.ruleState('loading'|'error'|'ok')·st.rules(서버 pjtRuleList)·st.ruleWarnings([{ partners, accounts }] 이름이 서로 포함되는 두 규칙이 같은 계정에 걸림). 규칙은 제안의 입력일 뿐 확정이 아니다.
 * 처음에는 접혀 있고(펼칠 때 서버에서 읽는다), 불러오는 중·못 불러옴·목록을 서로 다르게 보여 "규칙이 없습니다"로 오해되지 않게 한다. nm = 프로젝트 id → 이름, dis = 처리 중 비활성 속성 */
function ruleSectionHtml(st, nm, dis) {
  const open = st.ruleOpen === true; const toggle = '<div class="jh-fin__donehead" data-pt-rules><button type="button" class="jh-btn" data-variant="ghost" data-pt-rules-toggle aria-expanded="' + (open ? 'true' : 'false') + '">거래처 규칙 ' + (open ? '접기 ▴' : '보기 ▾') + '</button></div>';
  if (!open) return '<section class="jh-card jh-fin__rules">' + toggle + '</section>';
  const wrap = (inner) => '<section class="jh-card jh-fin__rules">' + toggle + '<div class="jh-finance__pad">' + inner + '</div></section>';
  if (st.ruleState === 'loading') return wrap('<div class="jh-field__hint">거래처 규칙을 불러오는 중입니다.</div>');
  if (st.ruleState === 'error') return wrap('<div class="jh-alert" data-tone="danger" role="alert">거래처 규칙을 불러오지 못했습니다.</div><button type="button" class="jh-btn" data-pt-rules-retry' + dis + '>다시 불러오기</button>');
  const rules = Array.isArray(st.rules) ? st.rules : []; const warns = Array.isArray(st.ruleWarnings) ? st.ruleWarnings : [];
  const hint = '<div class="jh-field__hint">거래처 이름에 규칙의 거래처가 들어 있는 전표 줄은 이 규칙으로 프로젝트 제안이 만들어집니다. 규칙은 제안일 뿐이고 확정은 사람이 합니다. 이미 만든 제안은 바뀌지 않으며 새 전표부터 적용됩니다.</div>';
  const wHtml = warns.length ? '<div class="jh-fin__rulewarn" role="status">' + warns.map((w) => '<div>⚠ 겹침: ' + (w.partners || []).map(esc).join(' · ') + ' — 같은 계정(' + (w.accounts || []).map((a) => esc(accountName(a))).join(', ') + ')에 둘 다 걸립니다. 이름이 더 긴 규칙이 우선합니다.</div>').join('') + '</div>' : '';
  const add = '<div class="jh-fin__ptact"><button type="button" class="jh-btn" data-variant="secondary" data-pt-rule-add' + dis + '>규칙 추가</button></div>';
  if (!rules.length) return wrap(hint + '<div class="jh-field__hint">규칙이 없습니다. 자주 나오는 거래처를 규칙으로 두면 새 전표의 프로젝트 제안이 자동으로 만들어집니다.</div>' + add);
  const modeText = (r) => r.mode === 'manday' ? '그 달 공수 비율' : (r.pjt ? nm(r.pjt) + ' 하나' : '프로젝트 미지정');
  const row = (r) => '<div class="jh-fin__rule' + (r.active === false ? ' jh-fin__rule--off' : '') + '" data-pt-rule="' + esc(r.id) + '"><div class="jh-fin__ptinfo"><strong>' + esc(r.partner) + '</strong>' + (r.active === false ? ' <span class="jh-fin__chip jh-fin__chip--skip">꺼짐</span>' : '') + '<div class="jh-fin__ptmemo">' + (r.accounts || []).map((a) => esc(accountName(a))).join(' · ') + (r.note ? ' · ' + esc(r.note) : '') + (r.setByName ? ' · ' + esc(r.setByName) + ' 지정' : '') + '</div></div><div class="jh-fin__ptchips"><span class="jh-fin__chip">' + modeText(r) + '</span></div>'
    + '<div class="jh-fin__doneact"><button type="button" class="jh-btn" data-pt-rule-edit="' + esc(r.id) + '"' + dis + '>수정</button><button type="button" class="jh-btn" data-pt-rule-toggle="' + esc(r.id) + '"' + dis + '>' + (r.active === false ? '켜기' : '끄기') + '</button></div></div>';
  return wrap(hint + wHtml + rules.map(row).join('') + add);
}
/** 거래처 규칙 추가·수정 패널 안쪽 — rule 이 null 이면 새 규칙(거래처 칸이 열려 있고 방식은 "프로젝트 하나"), 있으면 수정(거래처 칸이 잠긴다 — 거래처를 바꾸면 새 규칙이 되어 옛 규칙이 남는다). 계정은 서버 허용 6개만, 방식이 "프로젝트 하나"일 때만 프로젝트 선택이 보인다 */
export function pjtRuleDialogHtml(rule, names) {
  const r = rule || {}; const nm = names || {}; const edit = !!rule; const mode = r.mode === 'manday' ? 'manday' : 'single'; const accs = Array.isArray(r.accounts) ? r.accounts.map(String) : [];
  const ids = Object.keys(nm).sort((a, b) => String(nm[a]).localeCompare(String(nm[b]), 'ko')); if (r.pjt && ids.indexOf(r.pjt) === -1) ids.push(r.pjt);
  const opts = '<option value=""' + (r.pjt ? '' : ' selected') + '>프로젝트 선택</option>' + ids.map((id) => '<option value="' + esc(id) + '"' + (id === r.pjt ? ' selected' : '') + '>' + esc(nm[id] || id) + '</option>').join('');
  return '<div class="jh-field"><label class="jh-field__label" for="rd-partner">거래처(이름에 포함되는 말, 2~40자)</label><input class="jh-input" id="rd-partner" data-rd-partner maxlength="40" value="' + esc(r.partner || '') + '"' + (edit ? ' disabled' : '') + ' placeholder="예: 가짜외주">' + (edit ? '<span class="jh-field__hint">거래처 이름은 바꿀 수 없습니다. 다른 거래처는 새 규칙으로 추가하세요.</span>' : '') + '</div>'
    + '<div class="jh-field"><span class="jh-field__label">적용 계정</span><div class="jh-fin__rulechecks">' + RULE_ACCOUNTS.map((c) => '<label class="jh-fin__rulecheck"><input type="checkbox" data-rd-acc value="' + c + '"' + (accs.indexOf(c) !== -1 ? ' checked' : '') + '> ' + esc(accountName(c)) + '</label>').join('') + '</div></div>'
    + '<div class="jh-field"><span class="jh-field__label">방식</span><div class="jh-fin__rulechecks"><label class="jh-fin__rulecheck"><input type="radio" name="rd-mode" data-rd-mode value="single"' + (mode === 'single' ? ' checked' : '') + '> 프로젝트 하나</label><label class="jh-fin__rulecheck"><input type="radio" name="rd-mode" data-rd-mode value="manday"' + (mode === 'manday' ? ' checked' : '') + '> 그 달 공수 비율</label></div></div>'
    + '<div class="jh-field" data-rd-pjtbox' + (mode === 'manday' ? ' hidden' : '') + '><label class="jh-field__label" for="rd-pjt">프로젝트</label><select class="jh-select" id="rd-pjt" data-rd-pjt>' + opts + '</select></div>'
    + '<div class="jh-field"><label class="jh-field__label" for="rd-note">메모(선택)</label><input class="jh-input" id="rd-note" data-rd-note maxlength="200" value="' + esc(r.note || '') + '"></div>'
    + '<label class="jh-fin__rulecheck"><input type="checkbox" data-rd-active' + (r.active === false ? '' : ' checked') + '> 이 규칙 켜기</label>';
}
export function pjtTagHtml(st) {
  const names = st.names || {}; const nm = (id) => esc(names[id] || id); const money = (v) => esc(won(Math.abs(v)));
  const total = (st.rows || []).length; const can = (st.rows || []).filter((r) => r.confirmable).length; const dis = st.busy ? ' disabled' : '';
  const head = '<div class="jh-finance__pad"><div class="jh-fin__ptstat"><strong>대기 ' + total + '줄</strong> · 확정할 수 있는 ' + can + '줄</div>' + (st.msg ? '<div class="jh-alert" data-tone="info" role="status">' + esc(st.msg) + '</div>' : '') + '</div>';
  if (!total) return '<div class="jh-fin__pjttag" aria-busy="' + (st.busy ? 'true' : 'false') + '">' + head + '<div class="jh-finance__pad">대기 중인 줄이 없습니다. 새 전표를 가져오면 여기에 나타납니다.</div>' + doneHtml(st, nm, dis) + ruleSectionHtml(st, nm, dis) + '</div>';
  const chip = (r) => {
    if (!r.hasProposal) return '<span class="jh-fin__chip jh-fin__chip--none">제안 없음 — 직접 지정 필요</span>';
    if (r.method === '제외') return '<span class="jh-fin__chip jh-fin__chip--skip">프로젝트에 붙이지 않음' + (r.note ? ' · ' + esc(r.note) : '') + '</span>';
    if (!r.splits.length) return '<span class="jh-fin__chip jh-fin__chip--none">' + esc(r.note || '직접 지정 필요') + '</span>';
    return r.splits.map((x) => '<span class="jh-fin__chip">' + nm(x.pjt) + ' ' + Math.round(1000 * x.amount / r.amount) / 10 + '%</span>').join('');
  };
  const pairSize = {}; (st.rows || []).forEach((r) => { pairSize[r.pair] = (pairSize[r.pair] || 0) + 1; });
  const rowHtml = (r) => '<div class="jh-fin__ptrow' + (pairSize[r.pair] > 1 ? ' jh-fin__pair' : '') + '" data-pt-pair="' + esc(r.pair) + '">'
    + '<input type="checkbox" data-pt-row="' + esc(r.id) + '"' + (r.confirmable ? '' : ' disabled') + (st.sel && st.sel[r.id] ? ' checked' : '') + (st.busy ? ' disabled' : '') + ' aria-label="' + esc(r.no) + ' 선택">'
    + '<div class="jh-fin__ptinfo"><strong>' + esc(r.no) + '</strong> · ' + esc(r.date) + ' · ' + esc(r.partner || '거래처 없음') + '<div class="jh-fin__ptmemo">' + esc(r.memo) + ' · ' + esc(r.account) + '</div></div>'
    + '<div class="jh-fin__ptchips">' + chip(r) + (r.warn ? '<div class="jh-fin__ptwarn">' + esc(r.warn) + '</div>' : '') + (!r.confirmable && r.hasProposal && r.splits.length === 0 && r.method !== '제외' ? '' : '') + '<button type="button" class="jh-btn jh-fin__ptedit" data-pt-edit="' + esc(r.id) + '"' + dis + '>직접 지정</button></div>'
    + '<div class="num jh-fin__ptamt">' + (r.side === 'D' && /^4/.test(r.account) ? '−' : '') + money(r.amount) + '</div></div>';
  const monthCard = (m) => {
    const pv = monthPreview(m.rows); const revs = Object.keys(pv.revenue).sort(); const costs = Object.keys(pv.cost).sort();
    const preview = '<div class="jh-fin__ptpreview" data-pt-net="' + pv.revenueTotal + '"><strong>미리보기</strong> — 확정하면 ' + (revs.length ? '매출 순액 ' + revs.map((k) => nm(k) + ' ' + money(pv.revenue[k])).join(' · ') + ' (합 ' + money(pv.revenueTotal) + ')' : '매출 순액 0원') + (costs.length ? ' · 프로젝트 원가 ' + costs.map((k) => nm(k) + ' ' + money(pv.cost[k])).join(' · ') + ' (합 ' + money(pv.costTotal) + ')' : '') + '</div>';
    const act = '<div class="jh-fin__ptact"><button type="button" class="jh-btn" data-pt-pick-month="' + esc(m.month) + '"' + (m.confirmableCount ? '' : ' disabled') + dis + '>이 달 전체 선택</button><button type="button" class="jh-btn" data-variant="secondary" data-pt-confirm-month="' + esc(m.month) + '"' + (m.confirmableCount ? '' : ' disabled') + dis + '>이 달 전부 확정 (' + m.confirmableCount + '줄)</button></div>';
    return '<section class="jh-card" data-pt-month="' + esc(m.month) + '"><div class="jh-panel__head"><h3>' + esc(m.month) + '</h3><span class="jh-fin__ptcount">' + m.count + '줄 · 확정 가능 ' + m.confirmableCount + '줄</span></div><div class="jh-finance__pad">' + m.rows.map(rowHtml).join('') + preview + act + '</div></section>';
  };
  const picked = (st.rows || []).filter((r) => st.sel && st.sel[r.id]).length;
  const bar = '<div class="jh-fin__ptbar" data-pt-bar role="region" aria-label="선택한 줄 확정"><span class="jh-fin__ptsel" data-pt-selcount>선택 ' + picked + '줄</span><span class="jh-fin__ptbarbtns"><button type="button" class="jh-btn" data-pt-clear' + dis + '>선택 해제</button><button type="button" class="jh-btn" data-variant="primary" data-pt-confirm-sel' + dis + '>선택한 줄 확정</button></span></div>';
  return '<div class="jh-fin__pjttag" aria-busy="' + (st.busy ? 'true' : 'false') + '">' + head + bar + (st.months || []).map(monthCard).join('') + doneHtml(st, nm, dis) + ruleSectionHtml(st, nm, dis) + '</div>';
}
